/* eslint-disable react/require-default-props */
import React from 'react';
import * as CheckboxPrimitive from '@radix-ui/react-checkbox';
import { Check, Minus } from '@hexa-ui/icons';
import type * as Stitches from '@stitches/react';
import { config } from '@hexa-ui/theme';
import {
  Box,
  ErrorIcon,
  ErrorText,
  Flex,
  Label,
  StyledCheckbox,
  StyledIndicator,
} from './Checkbox.styles';

type CheckboxPrimitiveProps = React.ComponentProps<typeof CheckboxPrimitive.Root>;
type CheckboxVariants = Omit<Stitches.VariantProps<typeof StyledCheckbox>, 'error'>;
type CSSVariants = Stitches.CSS<typeof config>;

type ConditionalProps =
  | {
      label?: never;
      id?: string;
    }
  | {
      label: string;
      id: string;
    };

type BaseProps = {
  error?: string;
  size?: 'small' | 'medium';
  css?: CSSVariants;
} & ConditionalProps;

export type CheckboxProps = Omit<CheckboxPrimitiveProps, 'id' | 'asChild' | 'size'> &
  BaseProps &
  CheckboxVariants;

const CheckboxComponent = (
  { label, error, disabled = false, id, checked, css, size = 'medium', ...props }: CheckboxProps,
  forwardRef: React.ForwardedRef<HTMLButtonElement>
): JSX.Element => (
  <Flex css={css}>
    <StyledCheckbox
      size={size}
      disabled={disabled}
      checked={checked}
      error={Boolean(error)}
      id={id}
      {...props}
      ref={forwardRef}
    >
      <StyledIndicator>
        {checked === 'indeterminate' ? <Minus size="medium" /> : <Check size="medium" />}
      </StyledIndicator>
    </StyledCheckbox>
    <Box>
      <Label disabled={disabled} htmlFor={id}>
        {label}
      </Label>
      {error ? (
        <Flex css={{ marginTop: '$1', paddingLeft: '$4' }}>
          <ErrorIcon size="tiny" />
          <ErrorText>{error}</ErrorText>
        </Flex>
      ) : null}
    </Box>
  </Flex>
);

export const Checkbox = React.forwardRef(CheckboxComponent) as (
  props: CheckboxProps & {
    forwardRef?: React.ForwardedRef<typeof StyledCheckbox>;
  }
) => React.ReactElement;
